package com.tuap.backend.auth;
public record VerifiedSocialIdentity(AuthProvider provider,String providerSubject,String verifiedEmail,String givenName,String familyName){public VerifiedSocialIdentity{if(provider==null||provider==AuthProvider.LOCAL||providerSubject==null||providerSubject.isBlank())throw new IllegalArgumentException("Invalid external identity");}public static VerifiedSocialIdentity fromGoogle(VerifiedGoogleIdentity i){return new VerifiedSocialIdentity(AuthProvider.GOOGLE,i.subject(),i.email(),i.givenName(),i.familyName());}public static VerifiedSocialIdentity fromApple(VerifiedAppleIdentity i){return new VerifiedSocialIdentity(AuthProvider.APPLE,i.subject(),i.email(),null,null);}}
